/**
 * Municípios extraídos da página pública de referência em 25/10/2026.
 * Origem dos nomes: https://descomplicapro.com.br/simulacao/caixa (CaixaSimulator.js).
 * Limites financeiros municipais importados da planilha oficial do Agente Operador do FGTS,
 * TABELA_MUNICIPIOS_VIGENCIA_01JAN2026.xlsx, vigente desde 01/01/2026.
 * Checklists e guias são indicativos do fluxo de referência, não exigências universais
 * nem prazos oficiais da CAIXA. Confirme documentos e procedimentos com a instituição.
 */

export interface CaixaCity {
  n: string;
  u: string;
  /** Limite MCMV habitacional popular para a menor faixa de renda, vigente em 01/01/2026. */
  l: number;
}

export interface ApplicantProfile {
  name: string;
  type: string;
  income: string;
  statementMonths: string;
  hasFgts36: boolean;
  useFgts: boolean;
  product: string;
  declaredIr: boolean;
  socialFactor: string;
}

export interface CaixaReferenceDocument {
  title: string;
  detail: string;
}

export interface CaixaDiagnosisGuide {
  title: string;
  subtitle: string;
  steps: readonly string[];
  deadline?: string;
}

export const CAIXA_APPLICANT_TYPES = [
  { value: "clt", label: "CLT / Servidor / Militar" },
  { value: "domestico", label: "Empregado doméstico" },
  { value: "aposentado", label: "Aposentado / Pensionista" },
  { value: "informal", label: "Informal / Autônomo / Liberal" },
  { value: "mei", label: "MEI" },
  { value: "empresario", label: "Sócio / Empresário" },
] as const;

export function createApplicant(index: number, name = ""): ApplicantProfile {
  return {
    name: name || `Proponente ${index + 1}`,
    type: "",
    income: "",
    statementMonths: "3",
    hasFgts36: false,
    useFgts: false,
    product: "mcmv",
    declaredIr: false,
    socialFactor: "none",
  };
}

/** Checklist indicativo; não determina elegibilidade, dispensa ou validade bancária. */
export function getApplicantDocuments(
  applicant: ApplicantProfile,
  phase: 1 | 2,
  applicantCount: number,
): CaixaReferenceDocument[] {
  const documents: CaixaReferenceDocument[] = [];
  const income = Number(applicant.income) || 0;
  const statementMonths = ["3", "6", "12"].includes(applicant.statementMonths)
    ? applicant.statementMonths
    : "3";
  if (phase === 1) {
    documents.push(
      {
        title: "Documento de identificação",
        detail: "RG, CNH, Carteira Funcional, Passaporte ou RNM.",
      },
      {
        title: "Comprovante de residência",
        detail:
          "Referência: documento emitido nos últimos 2 meses. Confirme a validade aceita pela CAIXA.",
      },
    );
    if (applicant.type === "clt") {
      documents.push({
        title: "Contracheques",
        detail:
          "Referência: 3 últimos contracheques ou o último com mês completo trabalhado. Confirme a comprovação exigida.",
      });
    }
    if (applicant.type === "domestico") {
      documents.push({
        title: "E-Social",
        detail:
          "Comprovante do vínculo doméstico. Referência: emissão há no máximo 2 meses; confirme a validade aceita.",
      });
    }
    if (applicant.type === "aposentado") {
      documents.push({
        title: "Extrato do INSS",
        detail:
          "Comprovante de benefício. Referência: emissão há no máximo 2 meses; confirme a validade aceita.",
      });
    }
    if (["informal", "mei"].includes(applicant.type)) {
      if (applicant.declaredIr) {
        documents.push({
          title: "Declaração de Imposto de Renda",
          detail:
            "Recibo e corpo da declaração do último exercício, quando declarada. A CAIXA confirma sua necessidade para o perfil.",
        });
      }
      documents.push({
        title: "Extratos bancários",
        detail: `${statementMonths} meses de extrato completo para comprovação da renda, conforme o período selecionado. Confirme o período exigido.`,
      });
    }
    if (applicant.type === "empresario") {
      documents.push({
        title: "Pró-labore ou IR + movimentação",
        detail: `Pró-labore ou IR do último exercício acompanhado de ${statementMonths} meses de extratos, conforme o período selecionado. Confirme a documentação exigida.`,
      });
    }
    return documents;
  }

  documents.push({
    title: "Certidão de estado civil",
    detail:
      "Nascimento para solteiro; casamento para casado; certidão averbada para divorciado ou viúvo. Confirme os documentos do seu estado civil.",
  });
  if (applicant.hasFgts36 || applicant.useFgts) {
    documents.push({
      title: "Carteira de Trabalho (CTPS)",
      detail: "Comprovação do vínculo e do tempo de FGTS.",
    });
  }
  if (applicant.useFgts) {
    documents.push({
      title: "Extrato atualizado do FGTS",
      detail:
        "Necessário para solicitar o uso do saldo no financiamento. O banco valida os demais requisitos.",
    });
  }
  if (applicant.product === "mcmv" && applicant.declaredIr) {
    documents.push({
      title: "Declaração de Imposto de Renda",
      detail: "Recibo de entrega e corpo da declaração.",
    });
  }
  // Mantém as condições de exibição do fluxo de referência. Não calcula fator social.
  if (applicant.product === "mcmv" && income > 0 && income <= 4000 && applicantCount === 1) {
    if (applicant.socialFactor === "child") {
      documents.push({
        title: "Fator Social — filho menor",
        detail:
          "Certidão de nascimento ou RG do filho menor de 18 anos. Confirme o enquadramento e a documentação com a CAIXA.",
      });
    }
    if (applicant.socialFactor === "relative") {
      documents.push({
        title: "Fator Social — parente até 3º grau",
        detail:
          "RG, CPF, certidão de estado civil e declaração do Fator Social, conforme referência. Confirme o enquadramento com a CAIXA.",
      });
    }
  }
  return documents;
}

